//
//  NationModel.swift
//  Global Thermal Nuclear War
//
//  Play as other nations (3.11.0). Any nation that exists in the start year can be played. Its cabinet comes from the
//  bundled research (Shared/Resources/nation_cabinets.json, generated by Documentation/cabinets/gen_compact.py from
//  cabinets.json: 33 nations, ~13,000 officeholders): the real holders on the start date, with generic titles for
//  that form of government where the record has a gap (names are never invented). Uncertain records are marked "?";
//  records after April 2026 are low-confidence, so later dates keep the last earlier holder marked
//  "(acting/unverified)". The way a leader falls follows the nation's government (no-confidence, coup, revolution,
//  party congress, junta decision, royal dismissal); U.S. impeachment and the U.S.-only systems (Congress, the War
//  Powers clock, the draft, statehood, named fleets) apply only when playing the United States. The computer runs
//  the U.S. like any other country.
//  Repository: https://github.com/kochj23/GTNW
//

import Foundation

/// The bundled cabinet data.
struct NationCabinets: Decodable {
    struct Generic: Decodable {
        let titles: [String: String]
        let removal: [String]
    }
    struct Period: Decodable {
        let from: String
        let to: String
        let name: String
        let gov: String
        let removal: [String]
    }
    struct Nation: Decodable {
        let id: String
        let name: String
        let periods: [Period]
        /// role → [name, title, from, to, flags ("u" uncertain, "a" acting)]
        let roles: [String: [[String]]]
    }
    let role_keys: [String]
    let generic: [String: Generic]
    let nations: [Nation]

    static let shared: NationCabinets? = {
        guard let url = Bundle.main.url(forResource: "nation_cabinets", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(NationCabinets.self, from: data)
    }()
}

/// How a leader falls, by form of government. Impeachment is the U.S. (or another republic's) process.
enum RemovalMechanism: String, Codable, CaseIterable {
    case impeachment, noConfidence, coup, revolution, partyCongress, juntaDecision, royalDismissal

    var title: String {
        switch self {
        case .impeachment: return "Impeachment"
        case .noConfidence: return "No-confidence vote"
        case .coup: return "Coup"
        case .revolution: return "Revolution"
        case .partyCongress: return "Party congress"
        case .juntaDecision: return "Junta decision"
        case .royalDismissal: return "Royal dismissal"
        }
    }

    /// What happens at each stage of the pressure (1…3); the 4th ends the game.
    func stageText(_ stage: Int) -> String {
        switch (self, stage) {
        case (.noConfidence, 1): return "Backbenchers grumble openly about the leadership."
        case (.noConfidence, 2): return "The opposition tables a motion of no confidence."
        case (.noConfidence, 3): return "The whips have lost control: the confidence vote is held at the next poll unless support recovers."
        case (.coup, 1): return "Reports of unrest among the officer corps."
        case (.coup, 2): return "Senior generals are meeting in secret."
        case (.coup, 3): return "Troops are moving toward the capital: a coup comes at the next poll unless the army is placated."
        case (.revolution, 1): return "Strikes and demonstrations spread through the cities."
        case (.revolution, 2): return "Mass protests fill the squares; the police waver."
        case (.revolution, 3): return "Barricades are up: the regime falls at the next poll unless order and support return."
        case (.partyCongress, 1): return "Murmurs of dissatisfaction in the Politburo."
        case (.partyCongress, 2): return "The Central Committee is convened in emergency session."
        case (.partyCongress, 3): return "An extraordinary party congress meets at the next poll to replace the leader unless support recovers."
        case (.juntaDecision, 1): return "The junta's members question the leader's judgement."
        case (.juntaDecision, 2): return "The junta meets without the leader."
        case (.juntaDecision, 3): return "The junta will vote to replace the leader at the next poll unless confidence returns."
        case (.royalDismissal, 1): return "The court lets its displeasure be known."
        case (.royalDismissal, 2): return "Rivals gain the monarch's ear."
        case (.royalDismissal, 3): return "The monarch will dismiss the government at the next poll unless favour returns."
        case (_, let s): return PopularityModel.impeachmentText(stage: s)
        }
    }

    var ending: DomesticEnding {
        switch self {
        case .impeachment: return .impeached
        case .noConfidence: return .noConfidence
        case .coup: return .coup
        case .revolution: return .revolution
        case .partyCongress: return .partyCongress
        case .juntaDecision: return .juntaDecision
        case .royalDismissal: return .royalDismissal
        }
    }
}

enum NationModel {
    /// Game country ids that differ from the research's ids.
    static func cabinetID(forGameID id: String) -> String { id == "SVN_VN" ? "VNM_S" : id }

    /// Records after this are low-confidence (research note): later dates keep the last earlier holder, unverified.
    static let lowConfidenceAfter = GameCalendar.date(year: 2026, month: 4, day: 30)

    /// "YYYY", "YYYY-MM" or "YYYY-MM-DD" (Gregorian, including Russian imperial dates) as the first day it covers.
    static func parse(_ s: String) -> Date? {
        let p = s.split(separator: "-").compactMap { Int($0) }
        guard let y = p.first else { return nil }
        return GameCalendar.date(year: y, month: p.count > 1 ? p[1] : 1, day: p.count > 2 ? p[2] : 1)
    }

    static func nation(_ gameID: String) -> NationCabinets.Nation? {
        let id = cabinetID(forGameID: gameID)
        return NationCabinets.shared?.nations.first { $0.id == id }
    }

    static func period(_ gameID: String, on date: Date) -> NationCabinets.Period? {
        nation(gameID)?.periods.last { (parse($0.from) ?? .distantPast) <= date && ($0.to.isEmpty || date < (parse($0.to) ?? .distantFuture)) }
            ?? nation(gameID)?.periods.last { (parse($0.from) ?? .distantPast) <= date }
    }

    struct Holder: Equatable {
        var name: String
        var title: String
        var uncertain: Bool
        var acting: Bool
        /// Only a generic title: the record has a gap here (or the nation has no data).
        var generic: Bool
        /// After April 2026: the last earlier holder, unverified.
        var unverified: Bool
        var display: String { generic ? "(no record)" : name + (uncertain ? " ?" : "") + (unverified ? " (acting/unverified)" : "") }
    }

    /// Who held a role on a date, or the generic title for that form of government.
    static func holder(_ gameID: String, role: String, on date: Date, government gov: String) -> Holder {
        let late = date > lowConfidenceAfter
        let cutoff = late ? lowConfidenceAfter : date
        if let list = nation(gameID)?.roles[role] {
            let match = list.last { r in
                guard r.count >= 5, let from = parse(r[2]), from <= cutoff else { return false }
                return late || r[3].isEmpty || date < (parse(r[3]) ?? .distantFuture)
            }
            if let r = match {
                return Holder(name: r[0], title: r[1], uncertain: r[4].contains("u"), acting: r[4].contains("a"), generic: false, unverified: late)
            }
        }
        let title = NationCabinets.shared?.generic[gov]?.titles[role] ?? role.replacingOccurrences(of: "_", with: " ").capitalized
        return Holder(name: "", title: title.isEmpty ? role.replacingOccurrences(of: "_", with: " ").capitalized : title,
                      uncertain: false, acting: false, generic: true, unverified: false)
    }

    /// Government type of a nation on a date: the research's, or a guess from the game's government type.
    static func governmentType(_ c: Country, on date: Date) -> String {
        if let p = period(c.id, on: date) { return p.gov }
        switch c.government {
        case .monarchy: return "constitutional_monarchy_parliamentary"
        case .communist: return "one_party_communist_state"
        case .military: return "military_junta"
        case .theocracy: return "theocratic_republic"
        case .authoritarian: return "personalist_dictatorship"
        case .democracy, .republic: return "presidential_republic"
        }
    }

    /// The office the player holds: the prime minister in parliamentary systems, the party chief in communist states,
    /// otherwise the head of state.
    static func leaderRole(government gov: String) -> String {
        if gov.contains("parliamentary") || gov == "dominion" { return "head_of_government" }
        if gov.contains("communist") { return "paramount_leader" }
        return "head_of_state"
    }

    /// How the leader falls. The United States always uses impeachment.
    static func removal(_ c: Country, on date: Date) -> RemovalMechanism {
        if c.id == "USA" { return .impeachment }
        let gov = governmentType(c, on: date)
        let list = period(c.id, on: date)?.removal ?? NationCabinets.shared?.generic[gov]?.removal ?? []
        if list.contains("no_confidence") || list.contains("constructive_no_confidence") { return .noConfidence }
        if list.contains("party_congress") { return .partyCongress }
        if list.contains("junta_decision") { return .juntaDecision }
        if list.contains("royal_dismissal") && gov.contains("absolute") { return .royalDismissal }
        if list.contains("impeachment") { return .impeachment }
        if list.contains("coup") { return .coup }
        if list.contains("revolution") { return .revolution }
        if gov.contains("parliamentary") { return .noConfidence }
        if gov.contains("communist") { return .partyCongress }
        return .coup
    }

    /// Cabinet roles → the Situation Room's advisor posts.
    static let advisorRoles: [(role: String, key: String)] = [
        ("foreign", "state"), ("defense", "defense"), ("finance", "economic"), ("intelligence", "cia"),
        ("military_chief", "nsa"), ("interior", "press"),
    ]

    /// The cabinet on a date: the other head (prime minister or head of state) as chief adviser plus the six posts.
    static func cabinet(for c: Country, on date: Date) -> [Advisor] {
        let gov = governmentType(c, on: date)
        let leader = leaderRole(government: gov)
        let second = leader == "head_of_government" ? "head_of_state" : "head_of_government"
        var out: [Advisor] = []
        for (i, slot) in ([(second, "whc")] + advisorRoles).enumerated() {
            let h = holder(c.id, role: slot.role, on: date, government: gov)
            if h.generic && slot.role == second && leader == "head_of_state" && gov.contains("presidential") { continue }
            var a = Advisor(id: "\(c.id)-\(slot.role)", name: h.display, title: h.title, department: slot.role.replacingOccurrences(of: "_", with: " ").capitalized,
                            bio: h.generic ? "No record for this office on this date; generic title for a \(gov.replacingOccurrences(of: "_", with: " "))."
                                 : "\(h.title) of \(c.name).\(h.acting ? " Acting." : "")\(h.uncertain ? " Dates uncertain." : "")",
                            expertise: 60, loyalty: 65, influence: 55, publicSupport: 50, hawkishness: 50, interventionism: 50,
                            fiscalConservatism: 50, adviceAreas: [], portraitColor: ["#4A90E2", "#D0021B", "#7ED321", "#F5A623", "#9013FE", "#50E3C2", "#B8E986"][i % 7])
            a.role = slot.key
            out.append(a)
        }
        return out
    }

    /// The leader the player plays on a date (for the new-game picker and play history).
    static func leader(for c: Country, on date: Date) -> Holder {
        let gov = governmentType(c, on: date)
        return holder(c.id, role: leaderRole(government: gov), on: date, government: gov)
    }
}

// MARK: - Evolving cabinets (3.12.2)

extension GameEngine {
    /// Each turn: while history and the game agree, officeholders change on their real dates.
    /// - The player's government (non-U.S. nations with data) follows history until the player's choices diverge:
    ///   the player makes an appointment (any departure is replaced by the player's acting appointee), wins an
    ///   election, or history records someone else taking the player's own office. After that it is the player's.
    /// - Computer-run nations with data keep their historical leaders (shown on the dossier) until their own story
    ///   diverges: a change of government, annexation or destruction.
    func processCabinets() {
        guard let gs = gameState, let me = gs.getPlayerCountry() else { return }
        let date = gs.currentDate
        if me.id != "USA", gs.shadow.cabinetFollowsHistory, NationModel.nation(me.id) != nil {
            let leader = NationModel.leader(for: me, on: date)
            if let start = gs.shadow.playerLeader, !leader.generic, leader.name != start {
                gs.shadow.cabinetFollowsHistory = false
                gs.shadow.post("History records \(leader.name) taking over as \(leader.title). In this game you remain in office; the cabinet is yours now.",
                               date: date, severity: 1)
            } else {
                for new in NationModel.cabinet(for: me, on: date) {
                    guard let i = gs.advisors.lastIndex(where: { $0.isActive && $0.role == new.role && $0.id.hasPrefix(me.id + "-") }),
                          gs.advisors[i].name != new.name else { continue }
                    let old = gs.advisors[i]
                    gs.advisors[i].status = .resigned
                    var a = new
                    a.role = new.role
                    gs.advisors.append(Advisor(id: "\(new.id)@\(GameCalendar.year(of: date))-\(gs.advisors.count)", name: a.name, title: a.title,
                                               department: a.department, bio: a.bio, expertise: a.expertise, loyalty: a.loyalty, influence: a.influence,
                                               publicSupport: a.publicSupport, hawkishness: a.hawkishness, interventionism: a.interventionism,
                                               fiscalConservatism: a.fiscalConservatism, adviceAreas: a.adviceAreas, portraitColor: a.portraitColor))
                    gs.advisors[gs.advisors.count - 1].role = new.role
                    gs.shadow.post("\(new.name) replaces \(old.name) as \(new.title).", date: date, severity: 1)
                }
            }
        }
        for c in gs.countries where c.id != me.id && NationModel.nation(c.id) != nil && !gs.shadow.divergedNations.contains(c.id) {
            let gov = c.government.rawValue
            if let first = gs.shadow.trackedGovernments[c.id], first != gov || c.isTerritory || c.isDestroyed {
                gs.shadow.divergedNations.insert(c.id)
                gs.shadow.leaderNames.removeValue(forKey: c.id)
                continue
            }
            gs.shadow.trackedGovernments[c.id] = gov
            let l = NationModel.leader(for: c, on: date)
            if !l.generic { gs.shadow.leaderNames[c.id] = "\(l.display), \(l.title)" }
        }
        self.gameState = gs
    }

    /// The player's choices take the government off history's script.
    func divergeCabinet() {
        guard let gs = gameState else { return }
        gs.shadow.cabinetFollowsHistory = false
        self.gameState = gs
    }
}
